const cds = require('../../cds')
const { getToken } = require('./token')
const { LruCache } = require('./LruCache')
const { isTimeoutError, getTimeoutError } = require('./error')

const LOG = cds.log('remote')

const _destinationCache = new LruCache(cds.env.remote.cache_size)

let BUFFER_MS

const SUPPORTED_AUTH_TYPES = { NoAuthentication: 1, BasicAuthentication: 1, OAuth2ClientCredentials: 1 }

const HEADERS_PREFIX = 'URL.headers.'
const QUERIES_PREFIX = 'URL.queries.'

const _decodeJwt = jwt => {
  try {
    const payload = JSON.parse(Buffer.from(jwt.split('.')[1], 'base64url').toString())
    const { zid, app_tid, zone_uuid, user_id, user_uuid } = payload
    return { tenant: zid || app_tid || zone_uuid, user: user_id || user_uuid }
  } catch {
    LOG.warn('Failed to decode JWT payload')
    return {}
  }
}

const _identity = jwt => {
  const { tenant, user } = (jwt ? _decodeJwt(jwt) : cds.context) ?? {}
  return { tenant, user: user?.id ?? user }
}

const _fetchDestination = async (uri, name, token, userJwt) => {
  const headers = { authorization: `Bearer ${token}` }
  // Note: Cloud SDK only sends x-user-token for OAuth2UserTokenExchange/OAuth2SAMLBearerAssertion
  if (userJwt) headers['x-user-token'] = userJwt
  LOG._debug && LOG.debug(`Fetching destination '${name}'`)

  const { timeout } = cds.env.remote
  const signal = AbortSignal.timeout(cds.utils.ms4(timeout))
  let res
  try {
    res = await fetch(`${uri}/destination-configuration/v1/destinations/${encodeURIComponent(name)}`, {
      headers,
      signal
    })
  } catch (e) {
    if (isTimeoutError(e)) throw getTimeoutError(e, `Fetching destination '${name}'`, timeout)
    throw e
  }

  if (res.status === 404) return null
  if (!res.ok) throw new Error(`Fetching destination '${name}' failed with status ${res.status}.`)
  return res.json()
}

const _processResponse = ({ destinationConfiguration: dc, authTokens }) => {
  if (!(dc.Authentication in SUPPORTED_AUTH_TYPES))
    LOG.warn(`Auth type ${dc.Authentication} is not yet supported. Falling back to best-effort.`)

  const authToken = authTokens?.[0]
  const headers = {}
  if (authToken?.error != null) throw new Error(`Destination returned auth token error: ${authToken.error}`)
  if (authToken?.http_header) headers[authToken.http_header.key.toLowerCase()] = authToken.http_header.value
  if (dc['sap-client']) headers['sap-client'] = dc['sap-client']

  const queryParameters = {}
  for (const [k, v] of Object.entries(dc)) {
    if (k.startsWith(HEADERS_PREFIX)) headers[k.slice(HEADERS_PREFIX.length).toLowerCase()] = v
    else if (k.startsWith(QUERIES_PREFIX)) queryParameters[k.slice(QUERIES_PREFIX.length)] = v
  }

  const expiresIn = authToken?.expiresIn && Number(authToken.expiresIn)

  return {
    url: dc.URL,
    authentication: dc.Authentication,
    expiresIn,
    ...(Object.keys(headers).length && { headers }),
    ...(Object.keys(queryParameters).length && { queryParameters })
  }
}

const _lookup = async (creds, destinationName, tenant, jwt) => {
  if (tenant) {
    const subscriberToken = await getToken(creds, tenant)
    const subscriberResult = await _fetchDestination(creds.uri, destinationName, subscriberToken, jwt)
    if (subscriberResult) {
      LOG._debug && LOG.debug(`Destination '${destinationName}' resolved for subscriber tenant '${tenant}'`)
      return _processResponse(subscriberResult)
    }
    LOG._debug &&
      LOG.debug(
        `Destination '${destinationName}' not found for subscriber tenant '${tenant}', falling back to provider`
      )
  }

  const providerToken = await getToken(creds)
  const providerResult = await _fetchDestination(creds.uri, destinationName, providerToken)
  if (providerResult) {
    LOG._debug && LOG.debug(`Destination '${destinationName}' resolved for provider tenant`)
    return _processResponse(providerResult)
  }

  throw new Error(`Destination '${destinationName}' not found.`)
}

const getDestination = async (destinationName, { jwt } = {}) => {
  const creds = cds.env.requires?.destinations?.credentials
  if (!creds?.uri || !creds?.clientid) {
    LOG._debug && LOG.debug('No Destination Service credentials found')
    return null
  }

  LOG._debug && LOG.debug(`Resolving destination '${destinationName}'`)

  const { tenant, user } = _identity(jwt)
  // JWT present but no tenant claim — skip cache to avoid cross-tenant pollution
  const cacheKey = jwt && !tenant ? undefined : [destinationName, tenant, user].filter(Boolean).join(':')
  if (!cacheKey) LOG._debug && LOG.debug(`Destination '${destinationName}': JWT has no tenant claim, skipping cache`)

  const cached = _destinationCache.get(cacheKey)
  if (cached) {
    LOG._debug && LOG.debug(`Destination '${destinationName}' served from cache`)
    return cached
  }

  const promise = _lookup(creds, destinationName, tenant, jwt)
    .then(resolved => {
      if (!resolved) return null
      const { expiresIn = 60 * 60, ...destination } = resolved
      const expiresInMs = expiresIn * 1000
      BUFFER_MS ??= cds.utils.ms4(cds.env.remote.cache_expiry_buffer)
      const ttl = Math.max(0, expiresInMs - BUFFER_MS)
      LOG._debug && LOG.debug(`Destination for '${cacheKey}' cached for ${ttl}ms`)
      _destinationCache.set(cacheKey, destination, ttl)
      return destination
    })
    .catch(err => {
      LOG.warn(`Failed to resolve destination '${destinationName}':`, err.message)
      _destinationCache.delete(cacheKey)
      throw err
    })

  // cache promise immediately to deduplicate concurrent in-flight requests
  _destinationCache.set(cacheKey, promise)
  return promise
}

module.exports = { getDestination }
